-- with a real curated bank before production use.
-- question_json shape:
--   {"prompt": "...", "passage": "...", "options": ["..","..","..",".."],
--    "answer_index": 0, "explanation": "..."}
-- ============================================================================

-- ================= Part 1: Photographs =================
INSERT INTO questions (part, mode, question_json, topic, level) VALUES
(1, 'practice', '{"prompt": "Look at the picture: A woman is standing at a podium, speaking into a microphone. An audience is seated in front of her.", "options": ["A woman is speaking into a microphone.", "A woman is sitting at a desk.", "A woman is holding a camera.", "A woman is cleaning the podium."], "answer_index": 0, "explanation": "Người phụ nữ đang đứng phát biểu vào micro trước khán giả."}'::jsonb, 'Office', 'beginner'),
(1, 'practice', '{"prompt": "Look at the picture: Several boxes are stacked on a loading dock. A worker is moving one box with a hand truck.", "options": ["Boxes are stacked on the shelves.", "A worker is moving a box with a hand truck.", "A worker is opening a door.", "Boxes are being painted."], "answer_index": 1, "explanation": "Công nhân đang di chuyển một thùng hàng bằng xe đẩy tay."}'::jsonb, 'Office', 'intermediate'),

-- ================= Part 2: Question-Response =================
(2, 'practice', '{"prompt": "When will the new software be installed?", "options": ["In the meeting room.", "Next Tuesday morning.", "The IT department did.", "Yes, it is new."], "answer_index": 1, "explanation": "Câu hỏi When (khi nào) cần đáp án chỉ thời gian."}'::jsonb, 'IT', 'beginner'),
(2, 'practice', '{"prompt": "Who is in charge of the marketing campaign?", "options": ["Ms. Lin is.", "It starts tomorrow.", "In the lobby.", "The campaign budget."], "answer_index": 0, "explanation": "Câu hỏi Who (ai) cần đáp án chỉ người."}'::jsonb, 'Marketing', 'intermediate'),

-- ================= Part 3: Conversations =================
(3, 'practice', '{"passage": "Woman: Did you finish the quarterly report? Man: Not yet. I need the sales figures from your team first. Woman: I will email them to you this afternoon.", "prompt": "What does the man need?", "options": ["The quarterly meeting time", "The sales figures", "A new computer", "An email address"], "answer_index": 1, "explanation": "Người đàn ông cần số liệu bán hàng từ nhóm của người phụ nữ."}'::jsonb, 'Office', 'intermediate'),
(3, 'practice', '{"passage": "Man: The printer on the second floor is not working again. Woman: I will call the technician. Can you use the one in the lobby for now? Man: Yes, that is fine.", "prompt": "What will the woman do?", "options": ["Buy a new printer", "Move to the second floor", "Call the technician", "Print the documents herself"], "answer_index": 2, "explanation": "Người phụ nữ sẽ gọi kỹ thuật viên."}'::jsonb, 'Office', 'intermediate'),

-- ================= Part 4: Talks =================
(4, 'practice', '{"passage": "Attention, passengers. Flight 312 to Singapore is now boarding at gate 14. Please have your boarding pass ready. We expect an on-time departure at 9:40.", "prompt": "Where is this announcement being made?", "options": ["At a train station", "At an airport", "At a hotel", "At a bus stop"], "answer_index": 1, "explanation": "Thông báo về chuyến bay và cổng lên máy bay diễn ra ở sân bay."}'::jsonb, 'Travel', 'beginner'),
(4, 'practice', '{"passage": "Good morning, everyone. As you know, our annual staff training begins next Monday. Please check your email for the full schedule, and remember to bring your ID badge on the first day.", "prompt": "What should listeners bring on the first day?", "options": ["A laptop", "Their ID badge", "A lunch box", "The training manual"], "answer_index": 1, "explanation": "Người nghe cần mang theo thẻ nhân viên vào ngày đầu tiên."}'::jsonb, 'HR', 'intermediate'),

-- ================= Part 5: Incomplete Sentences =================
(5, 'practice', '{"prompt": "The new manager will start working here ___ Monday.", "options": ["at", "on", "in", "for"], "answer_index": 1, "explanation": "Dùng giới từ on trước các ngày trong tuần: on Monday."}'::jsonb, 'Grammar', 'beginner'),
(5, 'practice', '{"prompt": "Employees are requested to submit their expense reports ___ the end of the month.", "options": ["until", "by", "from", "during"], "answer_index": 1, "explanation": "By the end of the month = trước cuối tháng (hạn chót)." }'::jsonb, 'Grammar', 'intermediate'),

-- ================= Part 6: Text Completion =================
(6, 'practice', '{"passage": "To all staff: The office will be closed next Friday for building maintenance. ---- (1) ---- All meetings scheduled for that day have been moved to Thursday.", "prompt": "Choose the best sentence for blank (1).", "options": ["We apologize for any inconvenience.", "The cafeteria is on the third floor.", "Please bring your own laptop.", "The new printer is very fast."], "answer_index": 0, "explanation": "Thông báo đóng cửa văn phòng cần lời xin lỗi vì sự bất tiện."}'::jsonb, 'Office', 'intermediate'),
(6, 'practice', '{"passage": "Dear Mr. Park, Thank you for your interest in our training program. ---- (1) ---- Your application has been received and is under review.", "prompt": "Choose the best sentence for blank (1).", "options": ["The weather is nice today.", "We will contact you within five business days.", "Our office has three floors.", "Please do not reply to this email."], "answer_index": 1, "explanation": "Sau khi nhận đơn, bước tiếp theo hợp lý là sẽ liên hệ trong 5 ngày làm việc."}'::jsonb, 'HR', 'intermediate'),

-- ================= Part 7: Reading Comprehension =================
(7, 'practice', '{"passage": "MEMO From: Facilities Team Subject: Parking lot repairs The north parking lot will be closed for repairs from June 3 to June 7. During this period, please use the south parking lot and allow extra time in the morning.", "prompt": "What is the purpose of the memo?", "options": ["To announce a new employee", "To inform staff about parking lot repairs", "To change office hours", "To invite staff to a meeting"], "answer_index": 1, "explanation": "Bản ghi nhớ thông báo về việc sửa chữa bãi đỗ xe phía bắc."}'::jsonb, 'Office', 'beginner'),
(7, 'practice', '{"passage": "Customer Review: I ordered the wireless keyboard last week. Delivery took only two days, and the product works perfectly. The only problem was that the box was slightly damaged, but customer service offered me a discount on my next purchase.", "prompt": "What did customer service offer the reviewer?", "options": ["A free keyboard", "Faster delivery", "A discount on the next purchase", "A full refund"], "answer_index": 2, "explanation": "Bộ phận chăm sóc khách hàng đã giảm giá cho lần mua tiếp theo."}'::jsonb, 'Customer Service', 'intermediate'),

-- ================= Placement quiz (12 questions) =================
(2, 'placement', '{"prompt": "Where did you put the client files?", "options": ["On your desk.", "At noon.", "Yes, I did.", "The client called."], "answer_index": 0, "explanation": "Câu hỏi Where (ở đâu) cần đáp án chỉ địa điểm."}'::jsonb, 'Office', 'beginner'),
(2, 'placement', '{"prompt": "Has the invoice been sent to the client yet?", "options": ["Yes, yesterday morning.", "The invoice is long.", "In the finance office.", "Mr. Chen did."], "answer_index": 0, "explanation": "Câu hỏi Yes/No cần đáp án xác nhận kèm thời gian."}'::jsonb, 'Finance', 'beginner'),
(3, 'placement', '{"passage": "Woman: The conference room is booked all afternoon. Man: Then let us meet in the cafeteria at two. Woman: Fine. I will bring the contract copies.", "prompt": "Where will they meet?", "options": ["In the conference room", "In the cafeteria", "In the lobby", "In the office"], "answer_index": 1, "explanation": "Họ sẽ gặp ở căng tin lúc 2 giờ."}'::jsonb, 'Office', 'beginner'),
(3, 'placement', '{"passage": "Man: Our flight has been delayed by two hours. Woman: Let me check if there is an earlier connection. Man: That would be great, thank you.", "prompt": "What is the problem?", "options": ["The flight is delayed", "The ticket is lost", "The airport is closed", "The luggage is missing"], "answer_index": 0, "explanation": "Vấn đề là chuyến bay bị hoãn hai tiếng."}'::jsonb, 'Travel', 'intermediate'),
(4, 'placement', '{"passage": "This is a reminder that all expense reports for March must be submitted by Friday. Late submissions will be processed next month.", "prompt": "When must the reports be submitted?", "options": ["By Friday", "Next month", "In March", "Every day"], "answer_index": 0, "explanation": "Báo cáo phải nộp trước thứ Sáu."}'::jsonb, 'Finance', 'beginner'),
(4, 'placement', '{"passage": "Welcome to our store. This weekend only, all winter jackets are thirty percent off. Members get an extra five percent discount at checkout.", "prompt": "What is on sale?", "options": ["Winter jackets", "Summer shirts", "Shoes", "Bags"], "answer_index": 0, "explanation": "Áo khoác mùa đông đang giảm giá 30%."}'::jsonb, 'Sales', 'beginner'),
(5, 'placement', '{"prompt": "She has worked for this company ___ 2019.", "options": ["since", "for", "from", "at"], "answer_index": 0, "explanation": "Since + mốc thời gian cụ thể: since 2019."}'::jsonb, 'Grammar', 'beginner'),
(5, 'placement', '{"prompt": "The delivery was delayed ___ heavy traffic on the highway.", "options": ["because", "because of", "although", "despite"], "answer_index": 1, "explanation": "Because of + cụm danh từ: because of heavy traffic."}'::jsonb, 'Grammar', 'intermediate'),
(5, 'placement', '{"prompt": "Neither the manager nor the employees ___ satisfied with the new policy.", "options": ["is", "are", "was", "has"], "answer_index": 1, "explanation": "Neither...nor... chia động từ theo chủ ngữ gần nhất (employees -> are)." }'::jsonb, 'Grammar', 'advanced'),
(6, 'placement', '{"passage": "We are pleased to announce that our new branch opens on May 1. ---- (1) ---- All customers are invited to the opening event.", "prompt": "Choose the best sentence for blank (1).", "options": ["The old branch will close next year.", "It is located at 45 Park Street.", "Parking is always difficult.", "We sell many products."], "answer_index": 1, "explanation": "Thông báo chi nhánh mới cần địa chỉ cụ thể."}'::jsonb, 'Sales', 'intermediate'),
(7, 'placement', '{"passage": "NOTICE: The elevator in Building B is out of service until further notice. Please use the stairs or the elevator in Building A. We apologize for the inconvenience.", "prompt": "What should people use instead?", "options": ["The stairs or the Building A elevator", "The parking lot", "The main entrance", "The service desk"], "answer_index": 0, "explanation": "Dùng cầu thang bộ hoặc thang máy tòa nhà A."}'::jsonb, 'Office', 'beginner'),
(7, 'placement', '{"passage": "Email: Dear team, Our supplier has raised prices by eight percent starting next quarter. We need to review our budget and find ways to reduce costs without lowering quality.", "prompt": "Why must the team review the budget?", "options": ["Because the supplier raised prices", "Because sales increased", "Because new staff joined", "Because the quarter ended"], "answer_index": 0, "explanation": "Nhà cung cấp tăng giá 8% nên cần xem lại ngân sách."}'::jsonb, 'Finance', 'intermediate');
